import { test, type Page } from '@playwright/test';

const API = '/api/v1';
const focusDesc = (page: Page) =>
  page.evaluate(() => {
    const a = document.activeElement as HTMLElement | null;
    if (!a) return 'none';
    return `${a.tagName} role=${a.getAttribute('role')} name=${a.getAttribute('aria-label') ?? a.textContent?.trim().slice(0, 40)} inDialog=${!!a.closest('[role=dialog]')}`;
  });

test('check editor + trend + promote', async ({ page, request }) => {
  const suites = (await (await request.get(`${API}/suites`)).json()) as { id: string; name: string }[];
  const suite = suites.find((s) => s.name === 'Orders quality')!.id;
  const e = await request.post(`${API}/admin/seasonal-periods`, {
    data: { name: 'Audit BF', kind: 'recurring', start_month: 11, start_day: 27, end_month: 11, end_day: 30 },
  });
  const entry = (await e.json()).id;
  const c = await request.post(`${API}/suites/${suite}/checks`, {
    data: {
      name: 'Audit per day',
      kind: 'anomaly',
      expectation_type: 'monitor:anomaly',
      config: { target_metric: 'period_row_count', date_column: 'order_date', yearly: true, seasonal_periods: [entry] },
      fail_threshold: 3,
    },
  });
  const check = (await c.json()).id;
  const day = (i: number) => new Date(Date.UTC(2026, 10, 20 + i)).toISOString();
  try {
    await page.route(`**${API}/suites/*/checks/${check}/baseline`, (route) =>
      route.fulfill({
        json: {
          kind: 'anomaly',
          captured_at: day(0),
          baseline: {
            version: 1,
            target_metric: 'period_row_count',
            window: 14,
            observations: Array.from({ length: 12 }, (_, i) => ({
              ts: day(i),
              value: i >= 7 && i <= 10 ? 5000 + i : 1000 + i,
              ...(i < 6 ? { source: 'backfilled' } : {}),
            })),
          },
        },
      }),
    );
    await page.route(`**${API}/suites/*/checks/${check}/history**`, (route) =>
      route.fulfill({
        json: [6, 7, 8].map((i) => ({
          run_id: `00000000-0000-4000-8000-00000000000${i}`,
          status: 'pass',
          metric_value: 0.3,
          created_at: day(i + 1),
          seasonal: {
            period_start: day(i).slice(0, 10),
            mean: i === 6 ? 1003 : 5050,
            stddev: i === 6 ? 10 : 120,
            yearly_applied: i !== 6,
            yearly_reason: i === 6 ? 'no_earlier_year' : null,
            expected: i === 6 ? null : 5000,
            declared_name: i === 6 ? null : 'Audit BF',
            banded: true,
            verdict_changed: i === 7,
          },
        })),
      }),
    );
    await page.route(`**${API}/suites/*/checks/${check}/seasonal-periods/detected`, (route) =>
      route.fulfill({
        json: {
          reason: null,
          periods: [
            {
              kind: 'seen_once',
              start: day(7).slice(0, 10),
              end: day(10).slice(0, 10),
              peak_ratio: 5,
              years_seen: 1,
              range: null,
              occurrences: [{ year: 2026, start: day(7).slice(0, 10), end: day(10).slice(0, 10), peak_ratio: 5, periods: 4, backfilled_periods: 0 }],
              declared: [],
            },
          ],
          thresholds: { ratio: 1.5, min_consecutive: 2, same_time_days: 7, level: 'median' },
          history: { unit: 'day', points: 12, backfilled: 6, evaluated: 5, first: day(0).slice(0, 10), last: day(11).slice(0, 10), years: 0 },
        },
      }),
    );
    await page.goto(`/suites/${suite}/checks/${check}/edit`);
    await page.getByRole('button', { name: 'Trend' }).waitFor();
    console.log('FORM', await page.locator('form').first().ariaSnapshot());
    // yearly off -> warning
    const yearly = page.getByRole('switch', { name: /Yearly/ });
    console.log('yearly switch count', await yearly.count());
    await page.getByRole('button', { name: 'Trend' }).focus();
    await page.keyboard.press('Enter');
    await page.waitForTimeout(1500);
    console.log('drawer open focus:', await focusDesc(page));
    const drawer = page.getByRole('dialog').last();
    console.log('DRAWER', await drawer.ariaSnapshot());
    await page.getByRole('button', { name: /Promote to calendar/ }).focus();
    await page.keyboard.press('Enter');
    await page.waitForTimeout(1000);
    console.log('promote open focus:', await focusDesc(page));
    console.log('PROMOTE', await page.getByRole('dialog', { name: 'Add this period to the calendar' }).ariaSnapshot());
    await page.keyboard.press('Escape');
    await page.waitForTimeout(1000);
    console.log('promote esc focus:', await focusDesc(page));
    await page.keyboard.press('Escape');
    await page.waitForTimeout(1000);
    console.log('drawer esc focus:', await focusDesc(page));
    // yearly toggle off to see warning
    if (await yearly.count()) {
      await yearly.focus();
      await page.keyboard.press('Space');
      await page.waitForTimeout(500);
      console.log('after yearly off:', await page.getByTestId('calendar-detach-warning').ariaSnapshot().catch(() => 'none'));
    }
  } finally {
    await request.delete(`${API}/suites/${suite}/checks/${check}`);
    await request.delete(`${API}/admin/seasonal-periods/${entry}`);
  }
});

