  resetTelemetryStatus,
  type TelemetryEventSpec,
  type TelemetrySettings,
} from '../../api/telemetry';
import { formatTimestamp } from '../../components/results/resultsFormat';
import { useAsyncAction } from '../../hooks/useAsyncAction';
import { useAsyncData } from '../../hooks/useAsyncData';
import { fetchFailure } from '../../utils/errors';

const SINK_LABEL: Record<TelemetrySettings['sink'], string> = {
  off: 'No sink configured',
  file: 'JSON-lines file',
  otlp: 'OpenTelemetry exporter',
};

function describeValues(values: string[] | 'integer'): string {
  return values === 'integer' ? 'a count' : values.join(', ');
}

/** The usage-telemetry opt-in, with the full event list it would send shown inline. */
export function TelemetryPanel() {
  const { state } = useAsyncData(() => getTelemetrySettings());
  const [local, setLocal] = useState<TelemetrySettings | null>(null);
  const { run, loading } = useAsyncAction('Could not change usage telemetry');
  const current = local ?? (state.status === 'ok' ? state.data : null);

  const onToggle = (next: boolean) =>
    void run(async () => {
      setLocal(await putTelemetrySettings(next));
      resetTelemetryStatus();
    });

  return (
    <Card title="Usage telemetry" size="small">
      {state.status === 'loading' && !current && (
        <Typography.Text type="secondary">Loading…</Typography.Text>
      )}
      {state.status === 'error' && !current && (
        <Alert
          type="error"
          showIcon
          title="Could not load the usage-telemetry settings"
          description={fetchFailure(state.error).message}
        />
      )}
      {current && (
        <Flex vertical gap={12}>
          <Flex align="center" gap={12} wrap>
            <Switch
              checked={current.stored}
              disabled={loading}
              loading={loading}
              onChange={onToggle}
              aria-label="Usage telemetry"
            />
            <Typography.Text strong>Record how this workspace is used</Typography.Text>
            <Tag color={current.enabled ? 'green' : 'default'}>
              {current.enabled ? 'Recording' : 'Off'}
            </Tag>
            <Tag>{SINK_LABEL[current.sink]}</Tag>
          </Flex>
          <Typography.Text type="secondary">
            Off by default. When on, DataQ records the events below as OpenTelemetry metrics and log
            events, to a file or collector your operator chose. Only event names, counts and the
            listed values are recorded: never a table or column name, SQL, a suite or check name, an
            email address or a credential. Nothing is sent to DataQ&apos;s authors. Turning it off
            takes up to 30 seconds to reach every DataQ process.
          </Typography.Text>
          {current.stored && current.sink === 'off' && (
            <Alert
              type="warning"
              showIcon
              title="Opted in, but nothing is recorded"
              description="This deployment has no telemetry sink (TELEMETRY_SINK is off). The operator has to set it to file or otlp before anything is recorded."
            />
          )}
          {current.stored && current.sink !== 'off' && !current.sink_ready && (
            <Alert
              type="warning"
              showIcon
              title="Opted in, but the sink could not be started"
              description="TELEMETRY_SINK is set, but DataQ could not start it (for example, the file path is not writable). Nothing is recorded; the server log says why."
            />
          )}
          <Collapse
            size="small"
            items={[
              {
                key: 'events',
                label: `What is recorded (${current.events.length} events)`,
                children: (
                  <Table<TelemetryEventSpec>
                    size="small"
                    rowKey="name"
                    pagination={false}
                    dataSource={current.events}
                    columns={[
                      {
                        title: 'Event',
                        dataIndex: 'name',
                        render: (name: string) => <Typography.Text code>{name}</Typography.Text>,
                      },
                      {
                        title: 'Recorded with',
                        dataIndex: 'attributes',
                        render: (attributes: TelemetryEventSpec['attributes']) => (
                          <Flex vertical gap={2}>
                            {Object.entries(attributes).map(([key, values]) => (
                              <Typography.Text key={key} style={{ fontSize: 12 }}>
                                <Typography.Text code>{key}</Typography.Text>:{' '}
                                {describeValues(values)}
                              </Typography.Text>
                            ))}
                          </Flex>
                        ),
                      },
                    ]}
                  />
                ),
              },
            ]}
          />
          {current.updated_at && (
            <Typography.Text type="secondary" style={{ fontSize: 12 }}>
              Last changed {formatTimestamp(current.updated_at)}
              {current.updated_by ? ` by ${current.updated_by}` : ''}.
            </Typography.Text>
          )}
        </Flex>
      )}
    </Card>
  );
}
import { Alert, Button, Flex, InputNumber, Popconfirm, Space, Switch, Tag, Typography } from 'antd';
import { useState } from 'react';

import type { CoverageDocument, EffectiveCoverage } from '../../api/coverage';
import {
  BASELINES,
  type CoverageDraft,
  documentOf,
  draftOf,
  invalidReason,
  isEmpty,
  LEVEL_LABEL,
  MAX_DEVIATIONS,
  MAX_WINDOW,
  MIN_WINDOW,
  sensitivityFrom,
  shapeFrom,
  shortensWindow,
  TIERS,
} from './coverageDraft';

interface Props {
  /** What this level stores now (`null` or `{}` = nothing). */
  stored: CoverageDocument | null;
  /** What each group resolves to when this level does not set it. */
  below: EffectiveCoverage;
  /** What automatic checks run on now, with this level applied. */
  current: EffectiveCoverage;
  /** Names this level in the switches: "Set for the workspace" / "Set for this table". */
  scope: string;
  /** The button that removes everything this level sets. */
  clearLabel: string;
  saving: boolean;
  onSave: (doc: CoverageDocument) => void;
  /** Remove everything this level sets. */
  onClear: () => void;
}

/**
 * Sensitivity for automatic baselines at one level (ADR 0047). Each group is either set here,
 * whole, or left to the level below, whose values are shown so the choice is informed.
 */
export function CoverageSettingsForm({
  stored,
  below,
  current,
  scope,
  clearLabel,
  saving,
  onSave,
  onClear,
}: Props) {
  const [edited, setEdited] = useState<CoverageDraft | null>(null);
  const saved = draftOf(stored);
  const draft = edited ?? saved;
  const reason = invalidReason(draft);
  const dirty = JSON.stringify(draft) !== JSON.stringify(saved);
  // The draft is kept until the parent shows the stored result (it remounts this form on
  // success), so a save that fails leaves what was typed.
  const clearShortens = shortensWindow(draftOf(null), below, current);
  const TRIM =
    'Automatic checks drop their older observations on their next run. If the window is lengthened again later, they wait for that history to build back up before scoring.';
  const set = (next: CoverageDraft) => setEdited(next);

  return (
    <Flex vertical gap={16}>
      {BASELINES.map(({ key, label }) => {
        const group = draft.sensitivity[key];
        const shown = group ?? below.sensitivity[key];
        return (
          <Flex key={key} vertical gap={6} data-testid={`coverage-${key}`}>
            <Flex align="center" gap={8} wrap>
              <Typography.Text strong>{label}</Typography.Text>
              <Switch
                size="small"
                checked={group !== null}
                disabled={saving}
                aria-label={`${scope}: ${label} thresholds`}
                onChange={(on) =>
                  set({
                    ...draft,
                    sensitivity: {
                      ...draft.sensitivity,
                      [key]: on ? sensitivityFrom(below, key) : null,
                    },
                  })
                }
              />
              <Typography.Text type="secondary">{scope}</Typography.Text>
              {group === null && <Tag>{LEVEL_LABEL[below.sensitivity[key].source]}</Tag>}
            </Flex>
            <Space wrap size="middle">
              {TIERS.map((tier) => (
                <Space key={tier.key} orientation="vertical" size={2}>
                  <Typography.Text type="secondary">{tier.label}</Typography.Text>
                  <InputNumber
                    aria-label={`${label} ${tier.label.toLowerCase()} deviations`}
                    min={0}
                    max={MAX_DEVIATIONS}
                    step={0.5}
                    value={shown[tier.key]}
                    disabled={group === null || saving}
                    onChange={(v) =>
                      group &&
                      set({
                        ...draft,
                        sensitivity: { ...draft.sensitivity, [key]: { ...group, [tier.key]: v } },
                      })
                    }
                  />
                </Space>
              ))}
            </Space>
          </Flex>
        );
      })}

      <Flex vertical gap={6} data-testid="coverage-baseline">
        <Flex align="center" gap={8} wrap>
          <Typography.Text strong>History</Typography.Text>
          <Switch
            size="small"
            checked={draft.baseline !== null}
            disabled={saving}
            aria-label={`${scope}: history`}
            onChange={(on) => set({ ...draft, baseline: on ? shapeFrom(below) : null })}
          />
          <Typography.Text type="secondary">{scope}</Typography.Text>
          {draft.baseline === null && <Tag>{LEVEL_LABEL[below.baseline.source]}</Tag>}
        </Flex>
        <Space wrap size="middle" align="end">
          <Space orientation="vertical" size={2}>
            <Typography.Text type="secondary">Runs compared</Typography.Text>
            <InputNumber
              aria-label="Runs compared"
              min={MIN_WINDOW}
              max={MAX_WINDOW}
              precision={0}
              value={(draft.baseline ?? below.baseline).window}
              disabled={draft.baseline === null || saving}
              onChange={(v) =>
                draft.baseline && set({ ...draft, baseline: { ...draft.baseline, window: v } })
              }
            />
          </Space>
          <Space orientation="vertical" size={2}>
            <Typography.Text type="secondary">Runs before scoring</Typography.Text>
            <InputNumber
              aria-label="Runs before scoring"
              min={MIN_WINDOW}
              max={MAX_WINDOW}
              precision={0}
              value={(draft.baseline ?? below.baseline).min_points}
              disabled={draft.baseline === null || saving}
              onChange={(v) =>
                draft.baseline && set({ ...draft, baseline: { ...draft.baseline, min_points: v } })
              }
            />
          </Space>
          <Space size={8}>
            <Switch
              checked={(draft.baseline ?? below.baseline).seasonality}
              disabled={draft.baseline === null || saving}
              aria-label="Compare the same weekday only"
              onChange={(on) =>
                draft.baseline &&
                set({ ...draft, baseline: { ...draft.baseline, seasonality: on } })
              }
            />
            <Typography.Text>Compare the same weekday only</Typography.Text>
          </Space>
          <Space size={8}>
            <Switch
              checked={(draft.baseline ?? below.baseline).yearly ?? false}
              disabled={draft.baseline === null || saving}
              aria-label="Compare with the same time in earlier years"
              onChange={(on) =>
                draft.baseline && set({ ...draft, baseline: { ...draft.baseline, yearly: on } })
              }
            />
            <Typography.Text>Compare with the same time in earlier years</Typography.Text>
            <Typography.Text type="secondary">
              Row count and freshness only. Each table keeps a year or more of daily history.
            </Typography.Text>
          </Space>
        </Space>
      </Flex>

      {reason && <Alert type="warning" showIcon title={reason} />}
      {!reason && dirty && shortensWindow(draft, below, current) && (
        <Alert type="warning" showIcon title="A shorter window trims history" description={TRIM} />
      )}
      <Space>
        <Button
          type="primary"
          loading={saving}
          disabled={!dirty || !!reason}
          onClick={() => {
            // A form that sets nothing is "remove what this level sets", not an empty save.
            if (isEmpty(draft)) onClear();
            else onSave(documentOf(draft));
          }}
        >
          Save
        </Button>
        {clearShortens ? (
          <Popconfirm
            title="This shortens the window"
            description={TRIM}
            okText={clearLabel}
            onConfirm={onClear}
            disabled={isEmpty(saved) || saving}
          >
            <Button disabled={isEmpty(saved) || saving}>{clearLabel}</Button>
          </Popconfirm>
        ) : (
          <Button disabled={isEmpty(saved) || saving} onClick={onClear}>
            {clearLabel}
          </Button>
        )}
      </Space>
    </Flex>
  );
}

import { Alert, Button, Card, Popconfirm, Table, Tag, Tooltip, Typography } from 'antd';
import type { ColumnsType } from 'antd/es/table';

import { type DetectedClassification, setAssetClassificationDismissed } from '../../api/assets';
import { useAsyncAction } from '../../hooks/useAsyncAction';
import { formatTimestamp } from '../results/resultsFormat';

const DETECTOR_LABEL: Record<string, string> = {
  email: 'email addresses',
  encoded: 'encoded blobs',
};

/**
 * Columns the profiler found PII-shaped values in (ADR 0049) — the second masking reason
 * nothing else on the page explains. A detection masks the column on every read path until a
 * workspace admin dismisses it here (audited) or a suite names it as its identifier column.
 */
export function DetectedMaskingPanel({
  assetId,
  entries,
  refreshedAt,
  canDismiss,
  onChanged,
}: {
  assetId: string;
  entries?: DetectedClassification[] | null;
  refreshedAt?: string | null;
  canDismiss: boolean;
  onChanged: () => void;
}) {
  const { run, loading } = useAsyncAction('Could not update the detection');

  // Absent (an older API) says nothing, so render nothing.
  if (entries === undefined) return null;
  if (entries === null) {
    return (
      <Alert
        type="warning"
        showIcon
        data-testid="detected-masking-unknown"
        title="Could not check whether the profiler has detected personal data here: reading the detections failed."
      />
    );
  }
  // Never profiled and nothing found: there is nothing to explain yet.
  if (entries.length === 0 && !refreshedAt) return null;

  const setDismissed = (column: string, dismissed: boolean) =>
    void run(async () => {
      await setAssetClassificationDismissed(assetId, column, dismissed);
      onChanged();
    });

  const columns: ColumnsType<DetectedClassification> = [
    {
      title: 'Column',
      dataIndex: 'column',
      render: (value: string) => <Typography.Text code>{value}</Typography.Text>,
    },
    {
      title: 'Looked like',
      dataIndex: 'detector',
      render: (value: string) => DETECTOR_LABEL[value] ?? value,
    },
    {
      title: 'First seen',
      dataIndex: 'first_detected_at',
      render: (value: string) => formatTimestamp(value),
    },
    {
      title: 'Last seen',
      dataIndex: 'last_detected_at',
      render: (value: string) => formatTimestamp(value),
    },
    {
      title: 'Masking',
      key: 'masking',
      render: (_: unknown, row: DetectedClassification) => {
        if (row.effect === 'dismissed') {
          return (
            <Tag data-testid={`detection-${row.column}-dismissed`}>
              dismissed {formatTimestamp(row.dismissed_at)}
            </Tag>
          );
        }
        if (row.effect === 'overridden_by_tag') {
          return (
            <Tooltip title="This column carries its own warehouse tag, which decides instead; the detection changes nothing.">
              <Tag data-testid={`detection-${row.column}-overridden`}>warehouse tag decides</Tag>
            </Tooltip>
          );
        }
        return (
          <Tag color="orange" data-testid={`detection-${row.column}-masked`}>
            masked
          </Tag>
        );
      },
    },
    ...(canDismiss
      ? [
          {
            title: '',
            key: 'actions',
            render: (_: unknown, row: DetectedClassification) =>
              row.dismissed ? (
                <Button
                  size="small"
                  disabled={loading}
                  onClick={() => setDismissed(row.column, false)}
                >
                  Restore masking
                </Button>
              ) : (
                <Popconfirm
                  title="Dismiss this detection?"
                  description="Failing samples will show this column's values again. The dismissal is recorded in the audit log."
                  okText="Dismiss"
                  onConfirm={() => setDismissed(row.column, true)}
                >
                  <Button size="small" danger disabled={loading}>
                    Dismiss
                  </Button>
                </Popconfirm>
              ),
          } satisfies ColumnsType<DetectedClassification>[number],
        ]
      : []),
  ];

  return (
    <Card size="small" title="Detected personal data" data-testid="detected-masking-panel">
      <Typography.Paragraph type="secondary">
        The profiler found values shaped like personal data in these columns, so failing samples
        mask them even though nobody classified them. A warehouse tag or a suite’s identifier column
        overrides a detection; so does a workspace admin dismissing it here. A column not listed is
        not thereby clean: only the values a profile saw were examined, and only for these two
        shapes.
        {refreshedAt && <> Last full profile {formatTimestamp(refreshedAt)}.</>}
      </Typography.Paragraph>
      {entries.length === 0 ? (
        <Typography.Text type="secondary" data-testid="detected-masking-none">
          Nothing detected in the last full profile.
        </Typography.Text>
      ) : (
        <Table
          size="small"
          rowKey="column"
          pagination={false}
          dataSource={entries}
          columns={columns}
        />
      )}
    </Card>
  );
}
import { Descriptions } from 'antd';

import { yearlyReasonLabel } from '../checks/seasonalTrendData';

type Obj = Record<string, unknown>;

const obj = (v: unknown): Obj | null =>
  v !== null && typeof v === 'object' && !Array.isArray(v) ? (v as Obj) : null;
const num = (v: unknown): number | null => (typeof v === 'number' ? v : null);
const str = (v: unknown): string | null => (typeof v === 'string' ? v : null);

function fmt(v: number | null): string {
  return v === null ? '—' : Number.isInteger(v) ? String(v) : v.toFixed(2);
}

/**
 * What a per-period anomaly result was judged on: the period, the yearly comparison (or why it did
 * not apply), the declared calendar entry the period fell inside, and whether the calendar changed
 * the verdict. Renders nothing for any other result.
 */
export function SeasonalResultSummary({ observed }: { observed: unknown }) {
  const v = obj(observed);
  const period = obj(v?.period);
  if (!v || !period) return null;
  const yearly = obj(v.yearly);
  const declared = obj(v.declared);
  const inside = obj(declared?.inside);
  const history = obj(v.history);
  const start = str(period.start);
  const end = str(period.end);

  const items = [
    {
      key: 'period',
      label: 'Period judged',
      children: start && end && start !== end ? `${start} – ${end}` : (start ?? '—'),
    },
  ];
  if (yearly) {
    const applied = yearly.applied === true;
    items.push({
      key: 'yearly',
      label: 'Yearly comparison',
      children: applied
        ? `expected ${fmt(num(yearly.expected))} (level ${fmt(num(yearly.level))} × index ${fmt(num(yearly.index))}, from ${fmt(num(yearly.years))} earlier year${num(yearly.years) === 1 ? '' : 's'})`
        : `not applied: ${yearlyReasonLabel(str(yearly.reason))}; scored against the recent window`,
    });
  }
  if (num(v.mean) !== null && num(v.stddev) !== null) {
    items.push({
      key: 'band',
      label: 'Scored against',
      children: `${fmt(num(v.mean))} ± ${fmt(num(v.stddev))} (z ${fmt(num(v.z_score))})`,
    });
  }
  if (declared) {
    const occurrence = obj(inside?.occurrence);
    items.push({
      key: 'declared',
      label: 'Declared period',
      children: inside
        ? `inside ${str(inside.name) ?? 'an attached entry'}${occurrence ? ` (${str(occurrence.start)} – ${str(occurrence.end)})` : ''}${inside.first_year === true ? '; its first occurrence in the history' : ''}${inside.banded === false ? ', so a rise was not banded' : ''}`
        : 'outside every attached entry',
    });
    const changed = declared.verdict_changed;
    items.push({
      key: 'verdict',
      label: 'Calendar effect',
      children:
        changed === true
          ? `changed the verdict: without the calendar it would have been ${str(declared.verdict_without) ?? 'unbanded'} (z ${fmt(num(declared.z_score_without))})`
          : 'did not change the verdict',
    });
    const missing = Array.isArray(declared.missing) ? declared.missing.length : 0;
    if (missing > 0) {
      items.push({
        key: 'missing',
        label: 'Missing entries',
        children: `${missing} attached entr${missing === 1 ? 'y is' : 'ies are'} no longer on the calendar`,
      });
    }
  }
  if (history) {
    items.push({
      key: 'history',
      label: 'History behind it',
      children: `${fmt(num(history.observed))} measured by runs, ${fmt(num(history.backfilled))} seeded from the table`,
    });
  }

  return (
    <Descriptions
      size="small"
      column={1}
      bordered
      title="How this period was judged"
      items={items}
      data-testid="seasonal-result-summary"
    />
  );
}
import { Alert, Collapse, Flex, Tag, Typography } from 'antd';
import { useState } from 'react';

import { updateAsset } from '../../api/assets';
import {
  type AssetCoverageSettings,
  getAssetCoverageSettings,
  getCoverageSettings,
} from '../../api/coverage';
import { useAsyncAction } from '../../hooks/useAsyncAction';
import { useAsyncData } from '../../hooks/useAsyncData';
import { fetchFailure } from '../../utils/errors';
import { CoverageSettingsForm } from '../coverage-settings/CoverageSettingsForm';

/**
 * Workspace-admin control for one table's own sensitivity (ADR 0047). What it sets wins over
 * the workspace setting for this table's automatic checks; what it leaves alone follows it.
 */
export function CoverageSensitivityBlock({ assetId }: { assetId: string }) {
  const { state, reload } = useAsyncData(async () => {
    const [asset, workspace] = await Promise.all([
      getAssetCoverageSettings(assetId),
      getCoverageSettings(),
    ]);
    return { asset, workspace };
  });
  const [saved, setSaved] = useState<AssetCoverageSettings | null>(null);
  const { run, loading } = useAsyncAction('Could not save this table’s sensitivity');

  if (state.status === 'loading') return null;
  if (state.status === 'error') {
    return (
      <Alert
        type="error"
        showIcon
        title="Could not load this table’s coverage sensitivity"
        description={fetchFailure(state.error).message}
      />
    );
  }
  const asset = saved ?? state.data.asset;
  const overridden = asset.override !== null;
  // With no override the table follows the workspace, which may itself set nothing.
  const follows = [
    ...Object.values(asset.effective.sensitivity).map((group) => group.source),
    asset.effective.baseline.source,
  ].includes('workspace')
    ? 'Workspace setting'
    : 'Built-in default';
  const save = (config: AssetCoverageSettings['override']) =>
    void run(async () => {
      await updateAsset(assetId, { auto_coverage_config: config });
      try {
        setSaved(await getAssetCoverageSettings(assetId));
      } catch {
        // The override is stored; only the re-read failed. Load the block again rather than
        // report a failed save.
        setSaved(null);
        reload();
      }
    });

  return (
    <Collapse
      size="small"
      data-testid="coverage-sensitivity"
      items={[
        {
          key: 'sensitivity',
          label: (
            <Flex gap={8} align="center" wrap>
              <Typography.Text>Sensitivity of this table’s automatic checks</Typography.Text>
              <Tag color={overridden ? 'blue' : 'default'}>
                {overridden ? 'Set for this table' : follows}
              </Tag>
            </Flex>
          ),
          children: (
            <CoverageSettingsForm
              key={JSON.stringify(asset.override)}
              stored={asset.override}
              below={state.data.workspace.effective}
              current={asset.effective}
              scope="Set for this table"
              clearLabel="Use the workspace setting"
              saving={loading}
              onSave={save}
              onClear={() => save(null)}
            />
          ),
        },
      ]}
    />
  );
}

